        const body = response.b

Apollo Server 4 工程实践：context、插件、错误脱敏与安全必配项 - 资深码农 ~$ 资深码农 编程 数据库 接口 架构 运维 可观测 前端 音视频 工具 AI 生活 主页 / 接口、协议与安全 / GraphQL 的执行模型与运维成本 / Apollo Server 与 Client 实战 Apollo Server 4 工程实践：context、插件、错误脱敏与安全必配项 🏷️ Apollo Apollo Server 是常用的 GraphQL 服务实现，4.x 相比 3.x 是一次重构：不再内置各框架集成，钩子收进插件体系，错误处理接口也变了。这篇讲 对外服务的 Apollo Server 上线前必配的东西 ：context 边界、插件埋点、错误脱敏、自省与沙盒关闭、缓存失效。 💡 这篇怎么读 ① 用法 ：一份可以直接抄的 server 装配——context 怎么建、错误脱敏插件怎么写、生产关掉 introspection 与沙盒之后 IDE 和 codegen 怎么办，配必配项清单与四条验证命令。 ② 原理 ：Server 4 相对 3 变了什么、context 为什么是全局串行瓶颈、插件钩子的触发顺序与「为什么只能挂在 didResolveOperation」、formatError 作为唯一出口的职责、缓存失效的根因、订阅水平扩展与 Schema 管理。 ③ 场景 ：内部 BFF、对外网关、开放平台三种部署形态各该配到哪一步，加一张反模式速查表。 ① 用法 · 可以直接抄的 server 装配 下面这份初始化把必配项都写进去了： 关自省、禁沙盒、限请求体、深度上限、context 只做轻活、错误统一脱敏 。抄时重点看三处注释——它们标出了三个最常见的线上事故点。 每个钩子为什么挂在那个位置，见下面的原理层。 // server.js —— Apollo Server 4 完整初始化，可直接跑
import { ApolloServer } from '@apollo/server';
import { expressMiddleware } from '@apollo/server/express4';
import { ApolloServerPluginLandingPageDisabled } from '@apollo/server/plugin/disabled';
import { unwrapResolverError } from '@apollo/server/errors';
import express from 'express';
import http from 'http';
import { GraphQLError } from 'graphql';

const isProd = process.env.NODE_ENV === 'production';
const app = express();
const httpServer = http.createServer(app);

const server = new ApolloServer({
  typeDefs, resolvers,
  // 生产必须关自省：开着等于把完整 Schema 和所有参数送给攻击者
  introspection: !isProd,
  // 生产必须禁掉落地页沙盒，否则任何人都能在浏览器里直接打查询
  plugins: [
    ...(isProd ? [ApolloServerPluginLandingPageDisabled()] : []),
    metricsPlugin, complexityPlugin,
  ],
  validationRules: [depthLimit(10)],
  // formatError 是唯一的对外出口，脱敏只在这里做一次
  formatError: (formattedError, originalError) => {
    const raw = unwrapResolverError(originalError);
    // 业务侧主动抛的 GraphQLError 带了稳定 code，原样透出
    const code = formattedError.extensions?.code;
    if (code && code !== 'INTERNAL_SERVER_ERROR') {
