import subprocess, collections, itertools

# 模块前缀按你的目录结构改。粒度要和「将来可能拆出去的服务」对齐，
# 拆到比服务更细的包上算出来的数字没有意义
MODULES = ["src/order", "src/inventory", "src/pricing", "src/user", "src/report"]

def module_of(path):
    for m in MODULES:
        if path.startswith(m):
            return m
    return None

# 用 \x01 分隔提交块，避免文件名里的换行把解析搞乱；--no-merges 去掉合并噪声
log = subprocess.check_output(
    ["git", "log", "--since=6.months", "--no-merges",
     "--name-only", "--pretty=format:%x01%H"], text=True)

pairs, total, cross = collections.Counter(), 0, 0
for block in log.split("\x01")[1:]:
    lines = block.strip().splitlines()
    mods = {module_of(p) for p in lines[1:]} - {None}
    if not mods:
        continue                      # 只动了文档或构建脚本，不计入
    total += 1
    if len(mods) > 1:
        cross += 1
        for a, b in itertools.combinations(sorted(mods), 2):
            pairs[(a, b)] += 1        # 同时出现次数越高，越不该拆成两个服务

print("有效提交 %d，跨模块提交 %d，占比 %.1f%%" % (total, cross, cross * 100.0 / total))
for (a, b), n in pairs.most_common(10):
    print("%-16s %-16s 同时被改 %d 次" % (a, b, n)) 跨模块提交占比越高，拆分收益越小、协同成本越大。 共现次数最高的那几对模块要先合并再考虑拆 ，把它

