-- 用影响行数判业务失败，不要靠异常：RC 下这一行可能「扫到了却没改」，原因见原理层
COMMIT;
-- RR 与 SERIALIZABLE 下这段随时可能报 40001，应用必须重跑整个事务，重试模板见原理层

-- ② 会话或角色级兜底。这三项在生产库上不是可选项，而是防长事务的唯一手段
ALTER ROLE app       SET idle_in_transaction_session_timeout = '60s';  -- 专治开了事务去调外部接口
ALTER ROLE app       SET statement_timeout = '10s';
ALTER ROLE app       SET lock_timeout = '3s';
ALTER ROLE reporting SET statement_timeout = '10min';   -- 报表账号单独放宽，不要放宽全局 事务写对之后，第二个高频决策是 该用哪一档锁 。PG 的行锁有四档，加上两个修饰词和咨询锁，覆盖了几乎所有需求。查表就能选，不要一律 FOR UPDATE ： 要做什么 怎么做 注意什么 读一行，然后基于读到的值写回 SELECT ... FOR UPDATE ，或者升到 RR 并接受重试 RC 下不加锁的读会被并发覆盖； 加了锁事务就必须短 更新被外键引用的父表的非键列 直接 UPDATE ，它内部取 FOR NO KEY UPDATE 随手写 FOR UPDATE 会和子表外键检查的 FOR KEY SHARE 冲突，把子表并发插入全堵住 子表插入时保证父行存在 什么都不用加，外键检查自动取 FOR KEY SHARE 它只阻止删除父行与修改键列，冲突面最小，自己加锁反而更糟 多个 worker 抢任务 FOR UPDATE SKIP LOCKED ，放在子查询里 必须配 WHERE status = 'pending' 的部分索引，否则队列表一大就退化成全表扫 拿不到锁就立刻放弃 FOR UPDATE NOWAIT ，报 55P03 交给调用

向量检索性能调优：召回率、延迟与成本三角 - 资深码农 ~$ 资深码农 编程 数据库 接口 架构 运维 可观测 前端 音视频 工具 AI 生活 主页 / 数据库与缓存 / 向量检索的本质与代价：从精确 KNN 到近似 ANN / 向量检索性能优化 向量检索性能调优：召回率、延迟与成本三角 🏷️ 向量库优化 向量检索的性能问题几乎都能归到同一个三角： 召回率、延迟、成本，三个里最多同时保两个 。 近似最近邻本质上是拿准确性换速度，所以「优化」这件事没有单一目标——任何调参动作都只是在这个三角上挪位置。这篇讲怎么量化地挪，而不是凭感觉试。 ANN 索引结构本身的原理见站内「向量数据库总览」，pgvector 的具体参数与执行计划见站内「pgvector 能力边界与正确用法」，RAG 链路的工程问题见站内「RAG 检索侧数据工程」。 💡 这篇怎么读 ① 用法 ：调优的动手顺序（先建可复现的召回评测集，再调查询期参数，最后才动硬件）、一份在库内建 ground truth 并算 recall 的 SQL，以及「现象 → 调哪个参数 → 付什么代价」的对照表。 ② 原理 ：六个必看指标的定义与测法、瓶颈判断路径、三类参数调大调小的后果、量化与降维的压缩比与召回损失、内存为什么是硬约束、在线与离线为什么要反着调、写入与查询如何互相拖累、过滤条件的影响为什么常常大于向量参数。 ③ 场景 ：线上说「向量检索慢」时的排查顺序与命令，以及四类系统各自该停在召回-延迟曲线的什么位置。 ① 用法 · 调优的动手顺序：评测集 → 参数 → 硬件 调优顺序错了会白干很多轮。下面五步按「投入产出」和「不可逆程度」排过：前两步几乎零成本且能防止把事情搞坏，最后一步花钱最多、也最不该先做。 第几步 做什么 做完得到什么 跳过这步的后果 0 先向业务问清召回底线和延迟 SLA：漏一条最近邻的代价是什么 一个明确的工作点目标，例如「p99 在 50 ms 内、recall@10 不低于 0.95」 没有目标，任何参数都既可以说好也可以说坏，调优变成口水战 1 用真实查询建评测集，关掉索引扫描算出精确 Top-K 作为 ground truth，落盘存下来 可反复复用的基准，任何改动都能判断方向 没有基准就没有召回率，所有「变快了」的结论都可能是召回掉下去换来的 2 确认索引真的生效、且索引与向量驻留内存 排除掉最常见的两类伪性能问题 在一个根本没走索引、或正在读磁盘的系统上调参数，怎么调都没用 3 只扫查询期参数（ ef_search 、 nprobe ），画召回-延迟曲线并取拐点 当前索引结构下的最优工作点 直接去重建索引或换机型，代价大几个量级而收益可能就在这一步里 4 压小 k、给过滤字段建索引、按租户或时间分区 常常是最大的一笔提速，而且不损失召回 把本该由元数据索引解决的问题，错误地用放大召回参数去补 5 才轮到重建索引（改 m 与 ef_construction ）、量化、扩内存、加副本、分片 突破当前结构的上限 先做这一步，等于用钱和几小时的重建窗口，去换本可以免费拿到的收益 第 1 步是全部动作的地基，可以完全在库内完成，不需要另写服务。下面这段 SQL 建评测集、算 ground truth、再量出当前参数下的 recall@10 ；改一个 SET 重复执行最后一段，就得到曲线上的一个个点。 -- 1) 固定一份评测查询集。最好来自真实检索日志：随机向量在高维空间里彼此近似等距，测不出真实召回
CREATE TABLE eval_query AS
SELECT row_number() OVER () AS qid, embedding AS qvec
FROM doc_chunk TABLESAMPLE SYSTEM (1) LIMIT 500;   -- 暂时用库内向量占位，上线前务必换成线上 query 向量

-- 2) ground truth：关掉索引扫描强制精确暴力计算，结果落盘，后面反复复用不必重算
CREATE TABLE eval_truth (qid int, doc bigint);
SET enable_indexscan = off;            -- 只影响当前会话，不动全局配置
SET enable_indexonlyscan = off;
INSERT INTO eval_truth
SELECT q.qid, t.id
FROM eval_query q
CROSS JOIN LATERAL (
    SELECT c.id FROM doc_chunk c ORDER BY c.embedding <=> q.qvec LIMIT 10
) t;
RESET enable_indexscan;
