location /static/ {
    root /data/www;                 # 实际目录是 /data/www/static/
    expires 30d;
    access_log off;                 # 静态资源日志量极大，通常关掉
}

# 必须用 alias 的场景：URL 是 /assets/ 但磁盘目录叫 dist
location /assets/ {
    alias /data/site/dist/;         # 两边结尾斜杠必须都有
}

# 正则 location 下的 alias：捕获组必须显式拼回去
location ~ ^/download/(?<fname>.+)$ {
    alias /data/files/$fname;       # 少了捕获组就会拼成错误路径
    # 大文件下载：绕过 page cache，避免一个大文件把热数据全冲掉
    directio 4m;                    # 超过 4MB 的文件走 directio
    output_buffers 2 1m;
    aio threads;                    # 需要编译时带 --with-threads
    sendfile off;                   # directio 生效时 sendfile 自动失效
    limit_rate_after 10m;           # 前 10MB 全速，之后限速
    limit_rate 2m;
} 大文件服务里 sendfile 、 aio 、 directio 三者的内核行为主干篇已经讲过，这里只强调一条容易忘的结论： directio 生效时 sendfile 对同一个文件自动失效 ，两者不能叠加，所以「全局开了 sendfile 就够了」在大文件场景并不成立。 try_files 与 SPA 回退 try_files 属于 precontent 阶段，它按顺序探测每个候选项，第一个存在的就用，全都不存在时把最后一个参数当作 内部重定向目标或状态码 。常见误用是把最后一个参数写成文件名而不是 URI。 写法 行为 适用场景 try_files $uri $uri/ =404 文件与目录都不存在则 404 纯静态站点的安全默认值 try_files $uri $uri/ /index.html 回退到 SPA 入口，走一次 内部重定向 并重新匹配 location Vue 与 React 的 h

