var ErrBusy = errors.New("queue full")

type Task struct {
	Payload  []byte
	Deadline time.Time // 入队即打截止时间，出队先判过期
}

// Pipe 用有界 channel 做进程内队列。channel 本身就是有界阻塞队列，
// 容量按「可接受排队时间乘以稳定消费速率」反推，不要凭感觉写 10000。
type Pipe struct {
	ch       chan Task
	Rejected uint64 // 拒绝必须计数，静默丢弃等于故障不可见
	Expired  uint64
