var feeRules = map[string]FeeRule{
    "alipay":   func(a int64) int64 { return a * 6 / 1000 },
    "unionpay": func(a int64) int64 { return max64(a*5/1000, 100) }, // 千分之五且不低于 1 元
}

func Fee(ctx context.Context, channel string, amountCents int64) (int64, error) {
    r, ok := feeRules[channel]
    if !ok {
        // 未注册必须显式失败：静默按默认费率跑，事故要到对账时才发现
        return 0, fmt.Errorf("unknown fee channel %q", channel)
    }
    fee := r(amountCents)
    // 补回注册表丢掉的可搜索性：命中的 key 必须能在日志与链路里查到
    slog.InfoContext(ctx, "fee calculated", "channel", channel, "amount", amountCents, "fee", fee)
