}

// 超额部分直接丢弃但仍然返回成功，这样子进程不会收到 EPIPE 提前死掉，
// 也不会让 io.Copy 报 ErrShortWrite。
func (l *limitedWriter) Write(p []byte) (int, error) {
    total := len(p)
    if l.n <= 0 {
        return total, nil
    }
    if int64(total) > l.n {
        p = p[:l.n]
    }
    n, err := l.w.Write(p)
    l.n -= int64(n)
    if err != nil {
        return n, err
    }
    return total, nil
}

