// 这里选 cmp.Ordered 而不是 any，因为函数体里用到了大小比较
func Clamp[T cmp.Ordered](v, lo, hi T) T {
    if v < lo {
        return lo
    }
    if v > hi {
        return hi
    }
    return v
}
