// 不要引 golang.org/x/exp/constraints，它从未进标准库；进标准库的是 1.21 的 cmp 包
type Number interface {
    ~int | ~int8 | ~int16 | ~int32 | ~int64 |
        ~uint | ~uint8 | ~uint16 | ~uint32 | ~uint64 |
        ~float32 | ~float64
}

func Sum[T Number](xs []T) T {
    var total T // 零值对数值类型就是 0，不必写 T(0)
    for _, x := range xs {
        total += x
    }
    return total
}

// 三、最小的泛型类型：类型的实例化必须显式写出来，var s Stack[int]，推断不了
type Stack[T any] struct{ items []T }

func (s *Stack[T]) Push(v T) { s.items = append(s.items, v) }

// 返回 (T, bool) 而不是单个 T：让「空栈」和「栈顶恰好是零值」可以区分开
func (s *Stack[T]) Pop() (T, bool) {
    var zero T
    if len(s.items) == 0 {
        return zero, false
    }
    v := s.items[len(s.items)-1]
    s.items[len(s.items)-1] = zero // 置零让被弹出的元素可回收，元素是指针时这行很关键
    s.items = s.items[:len(s.items)-1]
    return v, true
}

